  "inlineSchema": "generator client {\n  provider = \"prisma-client\"\n  output   = \"../app/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Cliente {\n  id   String @id @default(cuid())\n  nome String\n\n  // Contato — o que a tela de cobrança precisa para responder \"de quem é o atraso\".\n  documento String?\n  email     String?\n  telefone  String?\n\n  contratos Contrato[]\n  servicos  Servico[]\n  createdAt DateTime   @default(now())\n}\n\nmodel Contrato {\n  id        String  @id @default(cuid())\n  cliente   Cliente @relation(fields: [clienteId], references: [id], onDelete: Cascade)\n  clienteId String\n\n  // Número curto para o advogado citar numa cobrança — ninguém lê um cuid().\n  numero   Int     @unique @default(autoincrement())\n  titulo   String?\n  processo String?\n\n  tipoPagamento TipoPagamento\n  valorTotal    Decimal       @db.Decimal(14, 2)\n\n  clausulaOriginal String\n\n  origem      OrigemRegistro @default(MANUAL)\n  arquivoNome String?\n\n  parcelas Parcela[]\n  despesas Despesa[]\n  servicos Servico[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([clienteId])\n}\n\nmodel Parcela {\n  id String @id @default(cuid())\n\n  contrato   Contrato @relation(fields: [contratoId], references: [id], onDelete: Cascade)\n  contratoId String\n\n  valor      Decimal  @db.Decimal(14, 2)\n  vencimento DateTime\n\n  pagamento Pagamento?\n\n  // Honorário de êxito só é devido se a causa der certo, e isso nenhum sistema\n  // adivinha: quem dá baixa é o advogado. Parcela baixada deixa de ser dívida —\n  // sai do previsto, do atraso e da cobrança. Diferente de \"devido e não pago\",\n  // que continua sendo atraso.\n  baixadaEm   DateTime?\n  motivoBaixa MotivoBaixa?\n  notaBaixa   String?\n\n  createdAt DateTime @default(now())\n\n  @@index([contratoId])\n  @@index([vencimento])\n}\n\nmodel Pagamento {\n  id String @id @default(cuid())\n\n  parcela   Parcela @relation(fields: [parcelaId], references: [id], onDelete: Cascade)\n  parcelaId String  @unique\n\n  valorPago Decimal  @db.Decimal(14, 2)\n  dataPago  DateTime @default(now())\n\n  createdAt DateTime @default(now())\n}\n\n// O outro lado do recebimento: o que o advogado cobra fora do contrato — a\n// consulta, o parecer, a audiência que não estava prevista. Não tem parcela\n// nem cláusula, então não cabe em Contrato; é cobrança única, e por isso o\n// recebimento mora na própria linha (recebidoEm) em vez de virar Pagamento.\nmodel Servico {\n  id     String @id @default(cuid())\n  numero Int    @unique @default(autoincrement())\n\n  descricao String\n  categoria CategoriaServico\n  valor     Decimal          @db.Decimal(14, 2)\n\n  realizadoEm DateTime\n  vencimento  DateTime\n  recebidoEm  DateTime?\n\n  cliente   Cliente? @relation(fields: [clienteId], references: [id], onDelete: SetNull)\n  clienteId String?\n\n  // Serviço prestado dentro de um caso já contratado (a audiência extra) —\n  // entra na receita daquele processo.\n  contrato   Contrato? @relation(fields: [contratoId], references: [id], onDelete: SetNull)\n  contratoId String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([vencimento])\n  @@index([clienteId])\n  @@index([contratoId])\n}\n\nenum CategoriaServico {\n  CONSULTA\n  PARECER\n  PETICAO\n  AUDIENCIA\n  ELABORACAO_CONTRATO\n  OUTROS_SERVICO\n}\n\n// O que sai. Tabela própria de propósito: Pagamento é 1-para-1 com Parcela e\n// significa \"recebi\" — sobrecarregá-lo com saídas quebraria o fluxo de caixa.\nmodel Despesa {\n  id     String @id @default(cuid())\n  numero Int    @unique @default(autoincrement())\n\n  descricao  String\n  categoria  CategoriaDespesa\n  valor      Decimal          @db.Decimal(14, 2)\n  vencimento DateTime\n  pagoEm     DateTime?\n\n  // A separação que importa: gasto do processo (ida ao juizado, custas,\n  // diligência) é o que come a margem do caso; gasto do escritório é custo\n  // fixo e não pertence a caso nenhum.\n  tipo TipoDespesa @default(PROCESSO)\n\n  fornecedor String?\n\n  contrato   Contrato? @relation(fields: [contratoId], references: [id], onDelete: SetNull)\n  contratoId String?\n\n  // quemPaga é o que o contrato prevê; cobradoEm é o que de fato aconteceu.\n  // Despesa de CLIENTE sem cobradoEm é dinheiro que o advogado adiantou e\n  // ainda não repassou — a origem silenciosa do prejuízo.\n  quemPaga  QuemPaga  @default(ADVOGADO)\n  cobradoEm DateTime?\n\n  origem        OrigemRegistro @default(MANUAL)\n  textoOriginal String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([vencimento])\n  @@index([contratoId])\n}\n\n// Só motivos que tornam o valor NÃO DEVIDO. Inadimplência não entra aqui:\n// nesse caso o honorário continua devido e a parcela segue em cobrança.\nenum MotivoBaixa {\n  SEM_EXITO\n  ACORDO_MENOR\n  DESISTENCIA\n  OUTRO\n}\n\nenum TipoPagamento {\n  FIXO\n  EXITO\n  MISTO\n}\n\nenum TipoDespesa {\n  PROCESSO\n  ESCRITORIO\n}\n\nenum QuemPaga {\n  CLIENTE\n  ADVOGADO\n}\n\n// Categorias concretas, no vocabulário do dia a dia — o advogado reconhece o\n// gasto sem precisar traduzir. As sete primeiras são de processo.\nenum CategoriaDespesa {\n  DESLOCAMENTO\n  CUSTAS\n  DILIGENCIA\n  CARTORIO\n  PERICIA\n  CORRESPONDENTE\n  OUTROS_PROCESSO\n  ESTRUTURA\n  SOFTWARE\n  TRIBUTOS\n  PESSOAL\n  OUTROS_ESCRITORIO\n}\n\nenum OrigemRegistro {\n  MANUAL\n  UPLOAD\n  DRIVE\n}\n",
